@dataclass
class WallConfig:
    raw_list: list[list[list[int]]]
    flat_list: list[int]
    num_orientations: int
    total_length: int

def find_valid_configurations(walls, gates, num_connectors) -> list[WallConfig]:
    raw_wall_gate_list = wall_inventory_to_list(walls, gates)
    raw_configs = find_configs(
        raw_wall_gate_list,
        4,
        50,
        num_connectors,
        10
    )
    res_configs = []

    # discard any config that doesn't use any gates at all
    # or requires more connectors than we have
    for config_raw_list in raw_configs:
        config_flat_list = list(chain.from_iterable(chain.from_iterable(config_raw_list)))
        wall_config = WallConfig(
            config_raw_list, 
            config_flat_list,
            len(config_raw_list),
            sum(config_flat_list)
            )

        print(wall_config)

        uses_gate = not set(gates).isdisjoint(wall_config.flat_list)
        has_enough_connector = len(wall_config.flat_list) <= num_connectors
        if uses_gate and has_enough_connector:
            res_configs.append(wall_config)
    return res_configs



# simply turning dict of wall and gates count into a flattened list 
def wall_inventory_to_list(dict1: dict[int, int], dict2: dict[int, int]) -> list[int]:
    combined = collections.Counter(dict1) + collections.Counter(dict2)
    return list(combined.elements())


# given a list of integer 
# find all possible combination of them that makes valid wall configs 
# result is list of list of list of int 
# list of config, each config a list of size 2 to 4 (one for each orientation)
# each direction is a list of size 2 for the opposite directions in this orientations 
# each list contains the wall lengths for that orientation
# from itertools import combinations
import random

def find_configs(
        pieces, 
        n_orientation, 
        max_total_length, 
        max_total_pieces,
        N # stop after finding N results
        ):
    results = []
    seen = set()

    assert(n_orientation in {2, 3, 4})
    
    # Filter out pieces larger than max_total_length and shuffle to promote diverse/random results
    valid_pieces = [p for p in pieces if p <= max_total_length]
    random.shuffle(valid_pieces)
    
    def backtrack(idx, current_sum, groups, pieces_used):
        # Stop early if we have found N results
        if len(results) >= N:
            return
            
        if current_sum > max_total_length or pieces_used > max_total_pieces:
            return
            
        # Check if the current group configuration is valid
        if pieces_used > 0:
            is_valid = True
            for g1, g2 in groups:
                # Both sides must be non-empty and sums must match
                if not g1 and not g2:
                    is_valid = False
                    break
                if sum(g1) != sum(g2):
                    is_valid = False
                    break
            
            if is_valid:
                # Normalize to prevent storing identical configs due to subgroup/group symmetry
                normalized_groups = tuple(
                    sorted(
                        tuple(sorted([tuple(sorted(g1)), tuple(sorted(g2))]))
                        for g1, g2 in groups
                    )
                )
                
                if normalized_groups not in seen:
                    seen.add(normalized_groups)
                    config_format = [(list(sub1), list(sub2)) for sub1, sub2 in normalized_groups]
                    results.append(config_format)
                    
                    if len(results) >= N:
                        return
                    
        if idx == len(valid_pieces):
            return
            
        p = valid_pieces[idx]
        
        # Option 1: Add the piece to one of the 2k subgroups
        if current_sum + p <= max_total_length and pieces_used + 1 <= max_total_pieces:
            # Shuffle the order of subgroups we try to increase variation
            options = [(i, j) for i in range(n_orientation) for j in range(2)]
            random.shuffle(options)
            
            for i, j in options:
                groups[i][j].append(p)
                backtrack(idx + 1, current_sum + p, groups, pieces_used + 1)
                groups[i][j].pop()
                if len(results) >= N:
                    return
                    
        # Option 2: Skip the current piece
        backtrack(idx + 1, current_sum, groups, pieces_used)

    initial_groups = [([], []) for _ in range(n_orientation)]
    backtrack(0, 0, initial_groups, 0)
    
    return results

# --- Example Usage ---
walls = {5: 2, 6: 2, 8: 2, 10: 2, 12: 2}
gates = {8: 1}
# walls = {5: 2, 6: 2, 7:1}
# gates = {}
solutions = find_valid_configurations(walls, gates, 100)
for sol in solutions:
    print(sol)